#!/usr/bin/env python3
import json, os, signal, socket, subprocess, sys, time
from pathlib import Path
ROOT=Path('/home/jaspersao/dev/91kvstore-performance-direct-20261120')
sys.path.insert(0,str(ROOT))
sys.path.insert(0,str(Path(os.environ.get('KVS_PERF_REPO','/home/jaspersao/dev/91kvstore'))/'tests'))
from run_single_qps import bench,ticks,KEY,VALUE
from test_two_vm_100k import Client

def ident(pid): return Path(f'/proc/{pid}/stat').read_text().split(') ',1)[1].split()[19]
def read(path): return json.loads(path.read_text())
def write(path,data): path.write_text(json.dumps(data,indent=2))
action=sys.argv[1]; a=json.loads(sys.argv[2])
directory=ROOT/'replication'/a['case']
if action=='ports':
    probes=[socket.socket() for _ in range(3)]
    try:
        for p in probes: p.bind((a['host'],0))
        result=[p.getsockname()[1] for p in probes]
    finally:
        for p in probes: p.close()
elif action=='start':
    directory.mkdir(parents=True)
    config=directory/'server.conf'
    if a['role']=='primary':
        mode='ebpf' if a['mode']=='ebpf' else 'socket'
        text=f"role=primary\nbind_ip={a['host']}\nservice_port={a['port']}\nrdma_port={a['rdma_port']}\nlog_level=info\nallocator=pool\npersistence_mode=none\nreplication_incremental_mode={mode}\n"
    else:
        text=f"role=replica\nbind_ip={a['host']}\nservice_port={a['port']}\nlog_level=info\nallocator=pool\npersistence_mode=none\nprimary_host={a['primary_host']}\nprimary_port={a['primary_port']}\n"
    config.write_text(text)
    argv=[a['repo']+'/bin/kvstore',str(config)]
    if a['role']=='primary' and a['mode']=='ebpf':
        with config.open('a') as config_file:
            config_file.write(f"replication_capture_port={a['capture_port']}\n")
    launch=argv
    with (directory/'server.log').open('wb') as log:
        p=subprocess.Popen(launch,cwd=directory,stdin=subprocess.DEVNULL,stdout=log,stderr=log,start_new_session=True)
    deadline=time.monotonic()+10
    while Path(f'/proc/{p.pid}/exe').resolve()!=Path(argv[0]).resolve():
        if p.poll() is not None or time.monotonic()>deadline: raise RuntimeError('service did not exec')
        time.sleep(.01)
    owner=dict(pid=p.pid,ticks=ident(p.pid),argv=argv)
    write(directory/'owner.json',owner)
    result=owner
elif action=='status':
    owner=read(directory/'owner.json'); pid=owner['pid']
    try:
        alive=ident(pid)==owner['ticks'] and Path(f'/proc/{pid}/cmdline').read_bytes().split(b'\0')[:-1]==[x.encode() for x in owner['argv']]
    except FileNotFoundError: alive=False
    result=dict(alive=alive,cpu_seconds=ticks(pid) if alive else None,log=(directory/'server.log').read_text())
elif action=='command':
    c=Client(a['host'],a['port'])
    try:
        kind,value=c.command(*[x.encode() for x in a['fields']])
        result=dict(kind=kind,value=value.decode() if isinstance(value,bytes) else value)
    finally: c.close()
elif action=='benchmark':
    owner=read(directory/'owner.json')
    before=ticks(a['capture_pid']) if a.get('capture_pid') else 0
    result=bench(a['port'],['HSET',KEY.decode(),VALUE.decode()],1,a['requests'],directory/(a['name']+'.log'),owner['pid'],a['host'])
    result['capture_cpu_seconds']=ticks(a['capture_pid'])-before if a.get('capture_pid') else 0
    write(directory/(a['name']+'.json'),result)
elif action=='visibility':
    primary=Client(a['host'],a['port']); replica=Client(a['replica_host'],a['replica_port'])
    values=[]
    try:
        for i in range(1000):
            value=(f'visibility_{i:08d}_'+'x'*128)[:128].encode()
            began=time.monotonic()
            if primary.command(b'HSET',KEY,value)!=('simple',b'OK'): raise RuntimeError('visibility write failed')
            while True:
                if replica.command(b'HGET',KEY)==('bulk',value): break
                if time.monotonic()-began>5: raise TimeoutError('Replica did not apply marker')
                time.sleep(.001)
            values.append((time.monotonic()-began)*1000)
    finally: primary.close(); replica.close()
    ordered=sorted(values)
    result=dict(samples=values,unit='ms',p50=ordered[499],p95=ordered[949],p99=ordered[989],max=ordered[-1],poll_interval_ms=1,note='separate serial probes: Primary submit through Replica observable read; includes polling and reply network time')
    write(directory/'visibility.json',result)
elif action=='stop':
    owner=read(directory/'owner.json'); pid=owner['pid']
    def alive():
        try:
            raw=Path(f'/proc/{pid}/stat').read_text().split(') ',1)[1].split()
            if raw[0]=='Z': return False
            if raw[19]!=owner['ticks']: return False
            actual=Path(f'/proc/{pid}/cmdline').read_bytes().split(b'\0')[:-1]
            if actual != [x.encode() for x in owner['argv']]: raise RuntimeError('process ownership changed')
            return True
        except FileNotFoundError: return False
    if alive(): os.kill(pid,signal.SIGTERM)
    deadline=time.monotonic()+10
    while alive() and time.monotonic()<deadline: time.sleep(.05)
    if alive(): raise RuntimeError('owned service did not stop')
    result=dict(stopped=True,log=(directory/'server.log').read_text())
else: raise RuntimeError(action)
print(json.dumps(result))

