"""One owned real BPF capture; suspend 135 clock correction as in prior measurements, restore on exit."""
import json,os,signal,subprocess,time
from pathlib import Path
ROOT=Path('/home/jaspersao/dev/91kvstore-performance-direct-20261120')
REPO=Path('/home/jaspersao/dev/91kvstore')

def atomic(name,value):
    p=ROOT/name;t=p.with_suffix('.next')
    t.write_text(json.dumps(value,indent=2)+'\n');os.chmod(t,0o644);t.replace(p)

def identity(pid):
    try:
        raw=Path(f'/proc/{pid}/stat').read_text().split(') ',1)[1].split()
        return None if raw[0]=='Z' else raw[19]
    except FileNotFoundError:return None

def interrupted(signum,frame):raise SystemExit(128+signum)

def main():
    if os.geteuid()!=0:raise SystemExit('Run this helper with sudo')
    if (ROOT/'capture-ready.json').exists() or (ROOT/'finished').exists():
        raise SystemExit('This run has already started; inspect its evidence before any retry')
    request=json.loads((ROOT/'capture-request.json').read_text())
    assert identity(request['pid'])==request['ticks'], 'Primary identity changed'
    expected=[str(REPO/'bin/kvstore'),str(ROOT/'replication/round-1-ebpf/server.conf')]
    assert Path(f'/proc/{request["pid"]}/cmdline').read_bytes().rstrip(b'\0').split(b'\0')==[x.encode() for x in expected]
    vmware=subprocess.check_output(['vmware-toolbox-cmd','timesync','status'],text=True).strip()
    assert vmware in ('Enabled','Disabled'),vmware
    ntp=subprocess.run(['systemctl','is-active','systemd-timesyncd'],capture_output=True,text=True).returncode==0
    original=dict(vmware=vmware,timesyncd_active=ntp)
    atomic('clock-original.json',original)
    child=None;errors=[]
    for sig in (signal.SIGTERM,signal.SIGHUP):signal.signal(sig,interrupted)
    try:
        subprocess.run(['vmware-toolbox-cmd','timesync','disable'],check=True)
        if ntp:subprocess.run(['systemctl','stop','systemd-timesyncd'],check=True)
        argv=[str(REPO/'bin/kvstore-ebpf-capture'),str(request['pid']),str(REPO/'build/ebpf_capture.bpf.o'),
              '--listen',f"172.16.145.135:{request['capture_port']}"]
        with (ROOT/'capture.log').open('wb') as log:
            os.chmod(ROOT/'capture.log',0o644)
            child=subprocess.Popen(argv,stdin=subprocess.DEVNULL,stdout=log,stderr=log)
        deadline=time.monotonic()+10
        while 'capture TCP listening' not in (ROOT/'capture.log').read_text(errors='replace'):
            if child.poll() is not None:raise RuntimeError((ROOT/'capture.log').read_text(errors='replace'))
            if time.monotonic()>deadline:raise TimeoutError('capture listener did not become ready')
            time.sleep(.05)
        atomic('capture-ready.json',dict(pid=child.pid,ticks=identity(child.pid),argv=argv,
            clock_paused=True,primary_pid=request['pid']))
        print('Clock corrections temporarily paused; capture TCP listening. Keep this terminal open.',flush=True)
        deadline=time.monotonic()+1800
        while not (ROOT/'finished').exists():
            if child.poll() is not None:raise RuntimeError('capture exited before measurements finished')
            if identity(request['pid'])!=request['ticks']:raise RuntimeError('Primary exited before measurements finished')
            if time.monotonic()>deadline:raise TimeoutError('benchmark completion marker not received')
            time.sleep(.1)
    finally:
        exit_code=None
        if child:
            if child.poll() is None:child.terminate()
            try:exit_code=child.wait(timeout=10)
            except subprocess.TimeoutExpired:
                child.kill();exit_code=child.wait(timeout=3);errors.append('capture required forced cleanup')
        if ntp:
            p=subprocess.run(['systemctl','start','systemd-timesyncd'],capture_output=True,text=True)
            if p.returncode:errors.append(p.stderr)
        p=subprocess.run(['vmware-toolbox-cmd','timesync','enable' if vmware=='Enabled' else 'disable'],capture_output=True,text=True)
        if p.returncode:errors.append(p.stderr)
        atomic('cleanup.json',dict(capture_exit=exit_code,clock_restored=not errors,
            original=original,errors=errors,vmware_after=subprocess.check_output(['vmware-toolbox-cmd','timesync','status'],text=True).strip(),
            timesyncd_active_after=subprocess.run(['systemctl','is-active','systemd-timesyncd'],capture_output=True,text=True).returncode==0))
        print('Capture stopped; original clock settings restored.' if not errors else 'Cleanup errors: '+str(errors),flush=True)
        if errors:raise RuntimeError(errors)
if __name__=='__main__':main()
